<?php $pageTitle='My orders | HEX CHEATS SHOP';$activePage='orders';require __DIR__.'/_head.php'; ?>
<section class="hx-page-heading"><p class="hx-eyebrow">ORDER HISTORY</p><h1>My orders</h1><p class="hx-muted">Payment status and fulfillment updates for your purchases.</p></section><section id="ordersList" class="hx-list"><div class="hx-loading">Loading orders…</div></section>
<script>(()=>{const box=document.getElementById('ordersList'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let csrf='';async function api(path,options={}){const headers={...(options.headers||{})};if(csrf&&options.method&&options.method.toUpperCase()!=='GET')headers['X-CSRF-Token']=csrf;const r=await fetch(path,{credentials:'same-origin',...options,headers});let d={};try{d=await r.json()}catch{}if(r.status===401){location.href='/login?next='+encodeURIComponent(location.pathname+location.search);throw Error('Please sign in again.')}if(!r.ok)throw Error(d.error||'Request failed.');return d}async function load(){try{const session=await api('/api/store/session');if(!session.authenticated){location.href='/login?next='+encodeURIComponent(location.pathname+location.search);return}csrf=session.csrf_token||'';const d=await api('/api/store/orders'),rows=d.orders||[];box.innerHTML=rows.length?rows.map(o=>{const pendingUpi=o.payment_method==='upi'&&o.status==='pending';const payment=pendingUpi?`<div class="hx-payment-actions">${o.payment_url?`<a class="hx-button hx-secondary" href="${esc(o.payment_url)}" target="_blank" rel="noopener noreferrer">Continue payment</a>`:''}<button class="hx-button hx-secondary" type="button" data-check-order="${esc(o.order_id)}">Check payment status</button></div>`:'';return `<article class="hx-panel hx-order"><div><b>${esc(o.product_name||'Product')}</b><div class="hx-muted">${esc(o.duration||'')} · ${new Date(Number(o.created_at)*1000).toLocaleString()}</div></div><span class="hx-status">${esc(o.status||'pending')}</span><b>₹${Number(o.amount||0).toFixed(2)}</b>${o.delivery_key?`<div class="hx-key">${esc(o.delivery_key)}</div>`:''}<small>Order ${esc(o.order_id||'')}</small>${payment}</article>`}).join(''):'<section class="hx-panel">No orders yet. <a href="/#catalog">Browse products</a></section>';box.querySelectorAll('[data-check-order]').forEach(button=>button.addEventListener('click',async()=>{const orderId=button.dataset.checkOrder;button.disabled=true;button.textContent='Checking…';try{await api('/api/store/checkouts/'+encodeURIComponent(orderId)+'/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await load()}catch(error){button.disabled=false;button.textContent='Check failed — retry';button.title=error.message}}))}catch(error){box.textContent=error.message||'Could not load orders.'}}load()})();</script>
